-- Ejecutar en Supabase -> SQL Editor -> New query -> Run.
-- Requiere hsr_conos.sql, que es el que crea la tabla weapons. Las columnas que
-- faltan las anade este mismo archivo.
--
-- Amplificadores (motores-W) de Zenless Zone Zero: los 99 que ya han salido.
--
-- Fuentes:
--   HoYoWiki, la wiki oficial de HoYoverse -> todo en espanol oficial: nombre,
--     rareza, especialidad, icono, ATQ base y stat avanzada a nivel 60, efecto
--     con sus cinco niveles, materiales de ascension y el agente al que
--     pertenece cada amplificador exclusivo.
--   Enka -> la rareza y la especialidad de los 5 mas nuevos, que la wiki
--     todavia no clasifica.
--
-- Los materiales de ascension no se copian de la wiki: en el juego todos los
-- amplificadores de una misma rareza cuestan lo mismo y solo cambia el
-- componente segun la especialidad, asi que se generan con esa tabla. La wiki
-- tenia erratas sueltas y nombres de materiales en otros idiomas.
--   Wiki de Zenless (Fandom) -> como se consigue, traducido al espanol.
--
-- "Crimson Moon Casket" no esta: la wiki la marca como proxima, todavia no ha
-- salido en el juego.
--
-- good_for viene rellenado con el agente de cada amplificador exclusivo, que es
-- un dato del juego. El resto se rellena a mano desde /admin.
--
-- Generado el 2026-09-11.

-- ---------------------------------------------------------------------------
-- Columnas que usa este archivo. Si ya existen, no hace nada; asi da igual el
-- orden en el que se ejecuten hsr_conos.sql, genshin_armas.sql y este.
-- ---------------------------------------------------------------------------
alter table public.weapons add column if not exists name_en text;
alter table public.weapons add column if not exists rarity text;
alter table public.weapons add column if not exists category text;
alter table public.weapons add column if not exists image_url text;
alter table public.weapons add column if not exists description text;
alter table public.weapons add column if not exists base_hp integer;
alter table public.weapons add column if not exists base_atk integer;
alter table public.weapons add column if not exists base_def integer;
alter table public.weapons add column if not exists sub_stat_name text;
alter table public.weapons add column if not exists sub_stat_value text;
alter table public.weapons add column if not exists passive_name text;
alter table public.weapons add column if not exists passive_levels jsonb;
alter table public.weapons add column if not exists how_to_get text;
alter table public.weapons add column if not exists ascension jsonb;
alter table public.weapons add column if not exists good_for text;

insert into public.weapons (
  id, game_id, name, name_en, rarity, category, image_url, description,
  base_hp, base_atk, base_def, sub_stat_name, sub_stat_value, passive_name,
  passive_levels, how_to_get, ascension, good_for
)
values
  ('zzz-w-3', 'zenless-zone-zero', 'Batería de Demara (II)', 'Demara Battery Mark II', 'A', 'Aturdidor', 'https://act-upload.hoyoverse.com/event-ugc-hoyowiki/2024/06/03/205556113/c0666bf89a5864bfc3ab5340dcef28c2_176584179317202744.png', 'Un amplificador personalizado para almacenamiento de energía. Gracias a su núcleo modificado, tiene una gran capacidad de salida de energía. El dueño de la tienda de juguetes lo considera su obra maestra. Sin embargo, poco tiempo después, Anby lo modificó para ajustarlo a sus hábitos. Pero, a juzgar por su extrema seriedad cada vez que le da mantenimiento, es probable que sus componentes no sean los más seguros...

«Es un arma, por supuesto que es peligrosa. Si no me electrocuta a mí, ¿cómo va a electrocutar al enemigo?»
–Respuesta de Anby mientras repara con cuidado el amplificador', null, 624, null, 'Impacto', '15%', 'Chispazo eléctrico', '["Aumenta el daño eléctrico en un 15%. Al golpear a un enemigo por medio de un contraataque o un ataque de apoyo, aumenta la Tasa de Energía del portador en un 18% durante 8 s.","Aumenta el daño eléctrico en un 17.5%. Al golpear a un enemigo por medio de un contraataque o un ataque de apoyo, aumenta la Tasa de Energía del portador en un 20.5% durante 8 s.","Aumenta el daño eléctrico en un 20%. Al golpear a un enemigo por medio de un contraataque o un ataque de apoyo, aumenta la Tasa de Energía del portador en un 23% durante 8 s.","Aumenta el daño eléctrico en un 22%. Al golpear a un enemigo por medio de un contraataque o un ataque de apoyo, aumenta la Tasa de Energía del portador en un 25% durante 8 s.","Aumenta el daño eléctrico en un 24%. Al golpear a un enemigo por medio de un contraataque o un ataque de apoyo, aumenta la Tasa de Energía del portador en un 27.5% durante 8 s."]'::jsonb, 'Tirando en el gacha permanente · Tirando en los canales exclusivos y de amplificadores · Regalo dentro de la historia', '[{"desde":10,"hasta":20,"creditos":9600,"materiales":[{"nombre":"Componente aturdidor","icono":"https://act-webstatic.hoyoverse.com/event-static-hoyowiki-admin/2024/07/05/fe3d9b3df343190aaa4ca2dbed091abf_663204191702084506.png","cantidad":3}]},{"desde":20,"hasta":30,"creditos":22400,"materiales":[{"nombre":"Componente aturdidor","icono":"https://act-webstatic.hoyoverse.com/event-static-hoyowiki-admin/2024/07/05/fe3d9b3df343190aaa4ca2dbed091abf_663204191702084506.png","cantidad":10}]},{"desde":30,"hasta":40,"creditos":48000,"materiales":[{"nombre":"Componente aturdidor potenciado","icono":"https://act-webstatic.hoyoverse.com/event-static-hoyowiki-admin/2024/07/05/62b5480180321b8a3acc1de450257ed7_5289654393386347030.png","cantidad":16}]},{"desde":40,"hasta":50,"creditos":80000,"materiales":[{"nombre":"Componente aturdidor potenciado","icono":"